// Log custody entry: pipeline initiated
const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const existingLog = Array.isArray(d.custody_log) ? d.custody_log : [];

  existingLog.push({
    timestamp: new Date().toISOString(),
    action: 'traitor_trace_initiated',
    performed_by: 'TRAITOR_TRACE_WORKFLOW',
    details: {
      evidence_id: d.id,
      source_url: d.source_url,
      source_platform: d.source_platform,
      pipeline_version: '2.0'
    }
  });

  results.push({ ...d, custody_log: existingLog });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  if (!d.source_url) {
    d.custody_log.push({
      timestamp: new Date().toISOString(),
      action: 'download_skipped',
      performed_by: 'TRAITOR_TRACE_WORKFLOW',
      details: { reason: 'no_source_url' }
    });
    results.push({ ...d, status: 'skipped', watermark_found: false });
    continue;
  }

  try {
    // Download with timeout and retry
    let imgBuffer = null;
    let attempts = 0;
    const maxAttempts = 3;

    while (attempts < maxAttempts && !imgBuffer) {
      attempts++;
      try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 15000);
        const imgResponse = await fetch(d.source_url, { signal: controller.signal });
        clearTimeout(timeout);

        if (!imgResponse.ok) throw new Error(`HTTP ${imgResponse.status}`);
        imgBuffer = Buffer.from(await imgResponse.arrayBuffer());
      } catch (fetchErr) {
        if (attempts >= maxAttempts) throw fetchErr;
        await new Promise(r => setTimeout(r, 1000 * attempts));
      }
    }

    // Calculate SHA-256 of downloaded file for integrity
    const crypto = require('crypto');
    const downloadHash = crypto.createHash('sha256').update(imgBuffer).digest('hex');

    // Send to image-hasher for watermark extraction
    const formData = new FormData();
    formData.append('file', new Blob([imgBuffer]), 'suspect.png');

    const extractRes = await fetch('http://image-hasher:8000/watermark/extract', {
      method: 'POST',
      body: formData
    });

    const extractData = await extractRes.json();
    const watermarkText = extractData.watermark || '';
    const watermarkFound = watermarkText.length > 0;

    // Confidence scoring: valid watermarks contain printable ASCII,
    // have reasonable length (8-128 chars), and don't contain only
    // repeated characters
    let confidence = 0;
    if (watermarkFound) {
      const printableRatio = (watermarkText.match(/[\x20-\x7E]/g) || []).length / watermarkText.length;
      const uniqueChars = new Set(watermarkText).size;
      const lengthOk = watermarkText.length >= 8 && watermarkText.length <= 256;

      confidence = 0;
      if (printableRatio > 0.9) confidence += 40;
      else if (printableRatio > 0.7) confidence += 20;
      if (uniqueChars > 3) confidence += 30;
      if (lengthOk) confidence += 30;
    }

    // Generate traitor_trace_id from watermark content
    const traceId = watermarkFound && confidence >= 50
      ? `TT-${crypto.createHash('md5').update(watermarkText).digest('hex').substring(0, 12).toUpperCase()}`
      : null;

    // Custody log: extraction completed
    d.custody_log.push({
      timestamp: new Date().toISOString(),
      action: watermarkFound ? 'watermark_extracted' : 'no_watermark_detected',
      performed_by: 'TRAITOR_TRACE_WORKFLOW',
      details: {
        download_hash_sha256: downloadHash,
        download_size_bytes: imgBuffer.length,
        download_attempts: attempts,
        watermark_found: watermarkFound,
        watermark_length: watermarkText.length,
        confidence_score: confidence,
        traitor_trace_id: traceId,
        extraction_method: 'lsb_steganography'
      }
    });

    results.push({
      evidence_id: d.id,
      tenant_id: d.tenant_id,
      evidence_name: d.evidence_name,
      source_platform: d.source_platform,
      watermark_found: watermarkFound,
      watermark_text: watermarkText || null,
      confidence: confidence,
      traitor_trace_id: traceId,
      download_hash: downloadHash,
      custody_log: d.custody_log,
      status: 'checked'
    });
  } catch (err) {
    d.custody_log.push({
      timestamp: new Date().toISOString(),
      action: 'extraction_failed',
      performed_by: 'TRAITOR_TRACE_WORKFLOW',
      details: { error: err.message, source_url: d.source_url }
    });
    results.push({
      evidence_id: d.id,
      tenant_id: d.tenant_id,
      custody_log: d.custody_log,
      status: 'error',
      error: err.message,
      watermark_found: false
    });
  }
}

return results;

// Final custody log entry for traitor-identified path
const items = $input.all();
for (const item of items) {
  const d = item.json;
  const log = Array.isArray(d.custody_log) ? d.custody_log : [];
  log.push({
    timestamp: new Date().toISOString(),
    action: 'traitor_trace_completed',
    performed_by: 'TRAITOR_TRACE_WORKFLOW',
    details: {
      result: 'traitor_identified',
      traitor_trace_id: d.traitor_trace_id,
      confidence: d.confidence,
      evidence_persisted: true
    }
  });
  d.custody_log = log;
}
return items;
